33|  track: Track | null;
34|  replayNonce: number;
35|  fadeSec: number;
36|  canPrev: boolean;
37|  onPrev: () => void;
38|  canSkip: boolean;
39|  onSkip: () => void;
40|  volume: number;
41|  muted: boolean;
42|  onVolumeChange: (volume: number) => void;
43|  onMutedChange: (muted: boolean) => void;
44|  modes: MusicMode[];
45|  current: MusicModeId | null;
46|  onAdvance: (to?: MusicModeId) => void;
47|  onEnded: (trackId: string) => void;
48|  playlistOn: boolean;
49|}) {
50|  const firstRef = useRef<HTMLAudioElement | null>(null);
51|  const secondRef = useRef<HTMLAudioElement | null>(null);
52|  const audibleRef = useRef(0);
53|  const levelRef = useRef<[number, number]>([1, 0]);
54|  const gainRef = useRef<[number, number]>([0, 0]);
55|  const segmentEndRef = useRef<string | null>(null);
56|  // Slider value and mute live in the reader (persisted prefs); refs
57|  // mirror the props so the engine never re-runs on volume moves.
58|  const volumeRef = useRef(volume);
59|  volumeRef.current = volume;
60|  const mutedRef = useRef(muted);
61|  mutedRef.current = muted;
62|  const fadeRef = useRef<number | null>(null);
63|  const loopArmedRef = useRef<string | null>(null);
64|  const trackRef = useRef<Track | null>(track);
65|  trackRef.current = track;
66|  const fadeSecRef = useRef(fadeSec);
67|  fadeSecRef.current = fadeSec;
68|  const onEndedRef = useRef(onEnded);
69|  onEndedRef.current = onEnded;
70|  const playingRef = useRef(false);
71|  const startedRef = useRef(false);
72|  const firstPlayRef = useRef(true);
73|
74|  // Scheduler fade when set, else the config default; never 0 mid session.
75|  function loopFadeSec() {
76|    return fadeSecRef.current > 0 ? fadeSecRef.current : MUSIC_CONFIG.crossfadeSec;
77|  }
78|  const [started, setStarted] = useState(false);
79|  const [playing, setPlaying] = useState(false);
80|  const requestPlayRef = useRef((_: Track, __: number) => {});
81|
82|  const [reducedMotion, setReducedMotion] = useState(
83|    () =>
84|      typeof window !== "undefined" &&
85|      !!window.matchMedia?.("(prefers-reduced-motion: reduce)").matches,
86|  );
87|
88|  useEffect(() => {
89|    const query = window.matchMedia?.("(prefers-reduced-motion: reduce)");
90|    if (!query) return;
91|    const onChange = (event: MediaQueryListEvent) => setReducedMotion(event.matches);
92|    query.addEventListener("change", onChange);
93|    return () => query.removeEventListener("change", onChange);
94|  }, []);
95|
96|  function applyLevels() {
97|    const els = [firstRef.current, secondRef.current];
98|    const audible = mutedRef.current ? 0 : volumeRef.current;
99|    els.forEach((el, i) => {
100|      if (el)
101|        el.volume = gainVolume(
102|          levelRef.current[i] ?? 0,
103|          audible,
104|          gainRef.current[i] ?? 0,
105|        );
106|    });
107|  }
108|
109|  function cancelFade() {
110|    if (fadeRef.current !== null) {
111|      cancelAnimationFrame(fadeRef.current);
112|      fadeRef.current = null;
113|    }
114|  }
115|
116|  // Assigned each render so handlers always see fresh refs. Fades from
117|  // the currently louder element to the newest track; a mid-fade request
118|  // cancels the pending fade and starts from current levels.
119|  requestPlayRef.current = (next: Track, durSec: number) => {
120|    const els = [firstRef.current, secondRef.current];
121|    const srcIdx = (levelRef.current[0] ?? 0) >= (levelRef.current[1] ?? 0) ? 0 : 1;
122|    const dstIdx = 1 - srcIdx;
123|    const srcEl = els[srcIdx];
124|    const dst = els[dstIdx];
125|    if (!srcEl || !dst) return;
126|    cancelFade();
127|    if (trackRef.current?.id !== next.id) loopArmedRef.current = null;
128|    trackRef.current = next;
129|    segmentEndRef.current = null;
130|    gainRef.current[dstIdx] = next.gainDb ?? 0;
131|    dst.src = next.src;
132|    dst.onloadedmetadata = () => {
133|      if (next.startSec > 0 && Number.isFinite(dst.duration) && next.startSec < dst.duration) {
134|        try {
135|          dst.currentTime = next.startSec;
136|        } catch {
137|          // Past the end; leave playback at zero.
138|        }
139|      }
140|    };
141|    if (!playingRef.current || durSec <= 0) {
142|      levelRef.current = [0, 0];
143|      levelRef.current[dstIdx] = 1;
144|      audibleRef.current = dstIdx;
145|      srcEl.pause();
146|      applyLevels();
147|      if (playingRef.current) void dst.play().catch(() => undefined);
148|      return;
149|    }
150|    if (playingRef.current) void dst.play().catch(() => undefined);
151|    const startSrc = levelRef.current[srcIdx] ?? 0;
152|    const startDst = levelRef.current[dstIdx] ?? 0;
153|    let t0 = performance.now();
154|    let prev = t0;
155|    const tick = (now: number) => {
156|      // Pause freezes the fade; resume continues from the frozen point.
157|      if (!playingRef.current) {
158|        t0 += now - prev;
159|        prev = now;
160|        fadeRef.current = requestAnimationFrame(tick);
161|        return;
162|      }
163|      prev = now;
164|      const t = Math.min(1, (now - t0) / (durSec * 1000));
165|      levelRef.current[srcIdx] = startSrc * Math.cos((t * Math.PI) / 2);
166|      levelRef.current[dstIdx] = startDst + (1 - startDst) * Math.sin((t * Math.PI) / 2);
167|      applyLevels();
168|      if (t < 1) {
169|        fadeRef.current = requestAnimationFrame(tick);
170|        return;
171|      }
172|      fadeRef.current = null;
173|      levelRef.current[srcIdx] = 0;
174|      levelRef.current[dstIdx] = 1;
175|      audibleRef.current = dstIdx;
176|      applyLevels();
177|      srcEl.pause();
178|    };
179|    fadeRef.current = requestAnimationFrame(tick);
180|  };
181|
182|  const trackId = track?.id ?? null;
183|  useEffect(() => {
184|    const next = trackRef.current;
185|    if (!started || !next) {
186|      // Before the first press, swaps only change src.
187|      if (!started && next) {
188|        const el = [firstRef.current, secondRef.current][audibleRef.current];
189|        if (el && !el.src.endsWith(next.src)) el.src = next.src;
190|        gainRef.current[audibleRef.current] = next.gainDb ?? 0;
191|        applyLevels();
192|      }
193|      return;
194|    }
195|    // The single start path: fade 0 on the very first press. replayNonce
196|    // re-cues the same track (one-track playlist wrap); nothing else is a dep
197|    // so volume, pause/play, and re-renders never restart the track.
198|    const dur = firstPlayRef.current ? 0 : fadeSecRef.current;
199|    firstPlayRef.current = false;
200|    requestPlayRef.current(next, dur);
201|  }, [started, trackId, replayNonce]);
202|
203|  useEffect(() => cancelFade, []);
204|
205|  function handleTimeUpdate(index: number, el: HTMLAudioElement) {
206|    const next = trackRef.current;
207|    if (!next || index !== audibleRef.current) return;
208|    const end = effectiveEnd(next.endSec, el.duration);
209|    if (!Number.isFinite(end)) return;
210|    // A non-looping or playlist track ends at the segment end, where the
211|    // media may keep playing, so fire the ended path once per play.
212|    if (!next.loop || playlistOn) {
213|      if (el.currentTime >= end && segmentEndRef.current !== next.id) {
214|        segmentEndRef.current = next.id;
215|        onEndedRef.current(next.id);
216|      }
217|      return;
218|    }
219|    const fade = loopFadeSec();
220|    if (end <= fade * 2) return;
221|    const remain = end - el.currentTime;
222|    if (remain <= fade && loopArmedRef.current !== next.id) {
223|      loopArmedRef.current = next.id;
224|      requestPlayRef.current(next, fade);
225|    } else if (remain > fade + 1) {
226|      loopArmedRef.current = null;
227|    }
228|  }
229|
230|  function handleEnded(index: number) {
231|    const els = [firstRef.current, secondRef.current];
232|    // An element that ends while a fade is running is the one fading out.
233|    if (index !== audibleRef.current || fadeRef.current !== null) {
234|      els[index]?.pause();
235|      return;
236|    }
237|    const next = trackRef.current;
238|    if (!next || segmentEndRef.current === next.id) return;
239|    if (next.loop && !playlistOn) {
240|      requestPlayRef.current(next, loopFadeSec());
241|      return;
242|    }
243|    segmentEndRef.current = next.id;
244|    onEndedRef.current(next.id);
245|  }
246|
247|  function toggle() {
248|    const both = [firstRef.current, secondRef.current];
249|    if (!startedRef.current) {
250|      startedRef.current = true;
251|      setStarted(true);
252|      playingRef.current = true;
253|      setPlaying(true);
254|      return;
255|    }
256|    if (playingRef.current) {
257|      for (const el of both) el?.pause();
258|      playingRef.current = false;
259|      setPlaying(false);
260|      return;
261|    }
262|    playingRef.current = true;
263|    setPlaying(true);
264|    let heard = false;
265|    both.forEach((el, i) => {
266|      if (el && (levelRef.current[i] ?? 0) > 0.02) {
267|        heard = true;
268|        void el.play().catch(() => undefined);
269|      }
270|    });
271|    const next = trackRef.current;
272|    if (!heard && next) requestPlayRef.current(next, 0);
273|  }
274|
275|  function changeVolume(value: number) {
276|    volumeRef.current = value;
277|    applyLevels();
278|    onVolumeChange(value);
279|  }
280|
281|  function toggleMute() {
282|    const next = !mutedRef.current;
283|    mutedRef.current = next;
284|    applyLevels();
285|    onMutedChange(next);
286|  }
287|
288|  const now = track ? nowPlaying(track) : null;
289|  const head = track
290|    ? [displayTitle(track.title), track.composer ?? track.artist]
291|        .filter((part): part is string => typeof part === "string" && part.length > 0)
292|        .join(" · ")
293|    : null;
294|  const showSource =
295|    !!track?.sourceUrl && !!track.artist && !!track.composer && track.artist !== track.composer;
296|
297|  return (
298|    <div className="player" role="region" aria-label="Music player" data-reduced-motion={reducedMotion}>
299|      <audio ref={firstRef} preload="auto" onTimeUpdate={(e) => handleTimeUpdate(0, e.currentTarget)} onEnded={() => handleEnded(0)} />
300|      <audio ref={secondRef} preload="auto" onTimeUpdate={(e) => handleTimeUpdate(1, e.currentTarget)} onEnded={() => handleEnded(1)} />
301|      <button type="button" className="skip" onClick={onPrev} disabled={!canPrev} aria-label="Previous track" title="Previous track">
302|        <svg width="17" height="17" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true">
303|          <rect x="2.5" y="3" width="2" height="10" rx="0.5" />
304|          <path d="M13.5 3.5v9L6 8z" />
305|        </svg>
306|      </button>
307|      <button type="button" className="skip play" onClick={toggle} aria-label={playing ? "Pause" : "Play"} title={playing ? "Pause" : "Play"}>
308|        {playing ? (
309|          <svg width="17" height="17" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true">
310|            <rect x="4" y="3" width="2.6" height="10" rx="0.5" />
311|            <rect x="9.4" y="3" width="2.6" height="10" rx="0.5" />
312|          </svg>
313|        ) : (
314|          <svg width="17" height="17" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true">
315|            <path d="M5 3.5v9l7.5-4.5z" />
316|          </svg>
317|        )}
318|      </button>
319|      <button type="button" className="skip" onClick={onSkip} disabled={!canSkip} aria-label="Next track" title="Next track">
320|        <svg width="17" height="17" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true">
321|          <path d="M2.5 3.5v9l7.5-4.5z" />
322|          <rect x="11.5" y="3" width="2" height="10" rx="0.5" />
323|        </svg>
324|      </button>
325|      <button
326|        type="button"
327|        className="skip"
328|        onClick={toggleMute}
329|        aria-pressed={muted}
330|        aria-label={muted ? "Unmute" : "Mute"}
331|        title={muted ? "Unmute" : "Mute"}
332|      >
333|        <svg width="17" height="17" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true">
334|          <path d="M2.5 6v4h2.6L9 13V3L5.1 6H2.5z" />
335|          {muted ? (
336|            <path
337|              d="M11 6.5l4 4m0-4l-4 4"
338|              fill="none"
339|              stroke="currentColor"
340|              strokeWidth="1.5"
341|              strokeLinecap="round"
342|            />
343|          ) : (
344|            <path
345|              d="M11 5.6a3.4 3.4 0 0 1 0 4.8M12.8 3.8a6 6 0 0 1 0 8.4"
