1|// Persisted music prefs: style, Chopin mode, volume, and muted. Storage
2|// can throw (private mode), so every access is guarded and falls back.
3|// Old values load safely: unknown fields are ignored, a missing or bad
4|// playlist, volume, or muted falls back to the defaults.
5|import type { PersistedMusicPrefs } from "@/core/music";
6|
7|export const MUSIC_PREFS_KEY = "lectoria.music.v1";
8|
9|export const DEFAULT_VOLUME = 0.8;
10|
11|function validVolume(value: unknown): number | null {
12|  return typeof value === "number" && Number.isFinite(value) && value >= 0 && value <= 1
13|    ? value
14|    : null;
15|}
16|
17|export function loadMusicPrefs(): PersistedMusicPrefs | null {
18|  try {
19|    if (typeof window === "undefined") return null;
20|    const raw = window.localStorage.getItem(MUSIC_PREFS_KEY);
21|    if (!raw) return null;
22|    const json: unknown = JSON.parse(raw);
23|    if (typeof json !== "object" || json === null) return null;
24|    const { style, volume, muted, playlist } = json as Record<string, unknown>;
25|    return {
26|      style: typeof style === "string" ? style : null,
27|      volume: validVolume(volume),
28|      muted: typeof muted === "boolean" ? muted : false,
29|      playlist: typeof playlist === "boolean" ? playlist : false,
30|    };
31|  } catch {
32|    return null;
33|  }
34|}
35|
36|export function saveMusicPrefs(prefs: PersistedMusicPrefs): void {
37|  try {
38|    if (typeof window === "undefined") return;
39|    window.localStorage.setItem(MUSIC_PREFS_KEY, JSON.stringify(prefs));
40|  } catch {
41|    // Private mode: playback continues without persistence.
42|  }
43|}

Read text file `core/music-modes.ts`.
1|// Ordered music modes: the style cycle plus the Chopin playlist mode.
2|// Pure: no env, no fetch, no audio. The control renders this list and the
3|// session advances through it, so neither knows the style-vs-playlist split.
4|import { CHOPIN_PLAYLIST_ID } from "./music-types";
5|import type { MusicManifest, Playlist } from "./music-types";
6|import { styleHasTracks } from "./music-selection";
7|
8|// A style id, or the Chopin playlist id.
9|export type MusicModeId = string;
10|
11|export interface MusicMode {
12|  id: MusicModeId;
13|  kind: "style" | "playlist";
14|  label: string;
15|}
16|
17|// The Chopin playlist, when the manifest defines it with tracks. The
18|// button stays hidden otherwise.
19|export function findChopinPlaylist(manifest: MusicManifest): Playlist | null {
20|  const found = manifest.playlists.find((p) => p.id === CHOPIN_PLAYLIST_ID) ?? null;
21|  return found && found.trackIds.length > 0 ? found : null;
22|}
23|
24|// Styles with tracks in manifest order, then the Chopin mode when available.
25|export function musicModes(manifest: MusicManifest): MusicMode[] {
26|  const modes = manifest.styles
27|    .filter((s) => styleHasTracks(manifest, s.id))
28|    .map((s): MusicMode => ({ id: s.id, kind: "style", label: s.name }));
29|  const playlist = findChopinPlaylist(manifest);
30|  if (playlist) modes.push({ id: playlist.id, kind: "playlist", label: playlist.label });
31|  return modes;
32|}
33|
34|// The mode the view sits on: the playlist id while it plays, else the style.
35|export function currentMode(view: {
36|  style: string | null;
37|  playlistOn: boolean;
38|}): MusicModeId | null {
39|  return view.playlistOn ? CHOPIN_PLAYLIST_ID : view.style;
40|}
41|
42|// Next in order, wrapping; an unknown or null current starts at the first.
43|// One mode returns itself.
44|export function nextMode(modes: MusicMode[], currentId: MusicModeId | null): MusicModeId | null {
45|  if (modes.length === 0) return null;
46|  const at = modes.findIndex((m) => m.id === currentId);
47|  return (modes[(at + 1) % modes.length] as MusicMode).id;
48|}

